#!/usr/bin/env python3
"""Bind source-cited FASED boundary/clock facts and deliberately unknown inputs."""
import argparse,hashlib,json,re,shutil
from pathlib import Path
R=Path(__file__).resolve().parents[1]
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
    p=argparse.ArgumentParser(__doc__);p.add_argument('--source',type=Path,default=R/'build/fased-service-source-v2');p.add_argument('--clock-proof',type=Path,default=R/'build/fased-service-clock-check-v1');p.add_argument('--observation',type=Path,default=R/'runs/fpga-rvv-page-transport-v1/memory-observation/observation.json');p.add_argument('--output',type=Path,required=True);a=p.parse_args();source=a.source.resolve();out=a.output.resolve()
    if out.exists():raise ValueError('fresh audit required')
    extraction=json.loads((source/'extraction.json').read_text());sv=source/'FireSim-generated.sv';assert sha(sv)==extraction['archived_SV_sha256']
    clock=json.loads((a.clock_proof/'report.json').read_text());assert clock['status']=='passed' and clock['clock_calendar']['relative_periods']==[2,1,10]
    inventory=Path(extraction['source_image_observability_inventory']);assert sha(inventory)==extraction['source_image_observability_inventory_sha256'];inv=json.loads(inventory.read_text())
    header=next(Path(p)for p in inv['input_sha256']if p.endswith('FireSim-generated.const.h'));assert sha(header)==inv['input_sha256'][str(header)]
    out.mkdir();shutil.copy2(a.observation,out/'candidate-startup-observation.json');observation=json.loads(a.observation.read_text())
    assert observation['selected_parameters']=={'writeLatency':30,'readLatency':30} and observation['sampled_before_driver_initialization'] and not observation['calibration_usable']
    files={'archived_SV':sv,'bridge':source/'rtl/FASEDMemoryTimingModel.sv','monitor':source/'rtl/MemoryModelMonitor.sv','MCR':source/'rtl/MCRFile_5.sv','timing':source/'scala-driver-snapshot/midas/src/main/scala/midas/models/dram/TimingModel.scala','latency':source/'scala-driver-snapshot/midas/src/main/scala/midas/models/dram/LatencyBandwidthPipe.scala','util':source/'scala-driver-snapshot/midas/src/main/scala/midas/models/dram/Util.scala','egress':source/'scala-driver-snapshot/midas/src/main/scala/midas/models/dram/EgressUnit.scala','full_bridge':source/'scala-driver-snapshot/midas/src/main/scala/midas/models/dram/FASEDMemoryTimingModel.scala','driver':source/'scala-driver-snapshot/midas/src/main/cc/bridges/fased_memory_timing_model.cc','header':header}
    def cite(key,needle):
        path=files[key];matches=[{'line':i+1,'text':line.strip()}for i,line in enumerate(path.read_text().splitlines())if needle in line]
        assert matches,(key,needle)
        return {'path':str(path),'sha256':sha(path),'matches':matches}
    facts=[]
    def fact(name,value,*evidence):facts.append({'name':name,'value':value,'evidence':[cite(*e)for e in evidence]})
    fact('archived_FASED_boundary',{'AXI_data_bits':64,'AXI_address_bits':33,'AXI_ID_bits':4,'maximum_burst_beats':8,'physical_read_requests':16,'physical_write_requests':16},('bridge','input  [32:0] hPort_hBits_axi4_ar_bits_addr'),('bridge','input  [63:0] hPort_hBits_axi4_w_bits_data'),('bridge','input  [3:0]  hPort_hBits_axi4_ar_bits_id'),('monitor','axi4_ar_bits_len <'),('monitor','axi4_aw_bits_len <'),('bridge',"writeMaxReqs <= 32'h10"),('bridge',"readMaxReqs <= 32'h10"))
    fact('source_reset_settings_only',{'readLatency':30,'writeLatency':30,'readMaxReqs':16,'writeMaxReqs':16,'relaxFunctionalModel':0,'admitted_hardware_defaults':False},('bridge',"readLatency <= 32'h1e"),('bridge',"writeLatency <= 32'h1e"),('bridge',"relaxFunctionalModel <= 32'h0"))
    fact('read_latency_origin','accepted AR; FIFO due timestamp then registered releaser',('latency','nastiReq.ar.fire'),('latency','readLatency + tCycle - egressUnitDelay'),('util','val currentRead = Queue(io.nextRead, 1, pipe = true)'),('egress','val egressUnitDelay = 1'))
    fact('write_latency_origin','paired AW and final W, in either arrival order',('timing','val newWReq ='),('latency','writePipe.io.enq.valid'),('latency','writeLatency + tCycle - egressUnitDelay'))
    fact('target_timing_advancement','one model-target edge per accepted bridge token; host backpressure may withhold the next token',('full_bridge','DecoupledHelper(hPort.toHost.hValid'),('full_bridge','val targetFire ='),('full_bridge','gate.CE := targetFire'),('full_bridge','val rReady'),('full_bridge','val bReady'))
    fact('functional_host_ordering','ingress/read/write egress are required; not supplied by LatencyPipe timing metadata',('full_bridge','val host_mem_idle'),('full_bridge','ingress.io.host_read_inflight'),('full_bridge','ingress.io.relaxed'),('full_bridge','readEgress.io.req.hValid'),('full_bridge','writeEgress.io.req.hValid'))
    fact('relative_clock_token_periods',[2,1,10],*[( 'archived_SV',f"timeToNextEdge_{i} <= 4'h{period:x}")for i,period in enumerate((2,1,10))])
    fact('relative_clock_0_consumers',['chiptop0 Iris uncore','chiptop0 Rocket tile2'],('archived_SV','assign chiptop0_clock_uncore = clockBridge_clocks_0_buffer_O'),('archived_SV','assign chiptop0_clock_tileClockGroup_rockettile_2 = clockBridge_clocks_0_buffer_O'))
    fact('relative_clock_1_consumers',['chiptop1 BringupSoC uncore','ep_2 FASED AXI tokens'],('archived_SV','assign chiptop1_clock_uncore = clockBridge_clocks_1_buffer_O'),('archived_SV','ep_2_axi4_ar_fwd_fired_0 <= ~clockBridge_clocks_1_enabled'))
    fact('relative_clock_2_consumers',['SerialTL Iris endpoint','SerialTL BringupSoC endpoint','harness RAM'],('archived_SV','assign chiptop0_serial_tl_0_clock_in = clockBridge_clocks_2_buffer_O'),('archived_SV','assign chiptop1_clock_serial_tl_0_clock_0 = clockBridge_clocks_2_buffer_O'),('archived_SV','assign ram_clock = clockBridge_clocks_2_buffer_O'))
    fact('histogram_semantics',{'bins':['count=0','1<=count<=2','3<=count<=4','5<=count<=8','constant0'],'occupancy_above_8_counted':False,'exhaustive':False},('timing','.zip(maximums)'),('MCR',"5'h8 == rIndex ? 32'h0"),('MCR',"5'hd == rIndex ? 32'h0"))
    fact('driver_override_policy','only explicit +mm settings are written; empty user config preserves hardware reset values; partially specified config requires hardware-default opt-in for omitted nonexcluded values',('driver','arg.find("+mm_")'),('driver','write(addr, user_it->second)'),('driver','if (!user_configuration.empty())'),('driver','if (useHardwareDefaults)'))
    fact('periodic_statistics','writable registers are excluded, so latency/max-request/relax values are not measured by periodic CSV',('driver','if (!addr_map.w_reg_exists((pair.first)))'))
    report={'schema':'iris.archived_FASED_boundary_audit.v1','facts':facts,'input_sha256':{str(p):sha(p)for p in [Path(__file__),source/'extraction.json',a.clock_proof/'report.json',a.observation,inventory,*files.values()]},'clock_calendar_proof':str(a.clock_proof/'report.json'),'repositories':extraction['repositories'],'candidate_startup_profile':{'read_latency':30,'write_latency':30,'read_max_requests':None,'write_max_requests':None,'relax_functional_model':None,'runtime_after_driver_initialization_verified':False,'units':'FASED ep_2/BringupSoC target-clock edges; source relative period1, Iris uncore/Rocket period2, SerialTL period10','status':'insufficient_for_full_service_admission','calibration_usable':False},'integration_gaps':['full bridge host-token/functional model is outside initial LatencyPipe SDK','BUFGCE default primitive behavior is not yet qualified in this native cut','actual MBUS/SerialTL/BringupSoC and width/clock adapters between post-L2-cork TL and this AXI boundary are not connected','readMaxReqs/writeMaxReqs/relaxFunctionalModel were not measured','startup observation precedes driver initialization; runtime values/overrides require exact launch argument closure','absolute clock frequency and all-hart clock mapping require further source qualification','source/loaded-image association is unverified','host backend service and backpressure are explicit external behavior','full source four-state knownness and arbitrary unreset RNG-order invariance are unqualified'],'hardware_contacted_by_audit':False,'loaded_image_verified':False,'whole_soc_timing_certified':False,'calibration_usable':False,'default_full_service_available':False}
    (out/'report.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'report_sha256':sha(out/'report.json'),'facts':len(facts),'default_full_service_available':False}))
if __name__=='__main__':main()
